import MenuCard from "./MenuCard";

export default function MenuGrid({ menu, addToCart }) {
  return (
    <div className="menu-grid">
      {menu.map(item => (
        <MenuCard key={item.id} item={item} addToCart={addToCart} />
      ))}
    </div>
  );
}
